class Solution:
    def longestCommonPrefix(self, strs: list[str]) -> str:
        if not strs:
            return ""

        for c in range(len(strs[0])):
            letter = strs[0][c]
            for r in range(len(strs)):
                if c >= len(strs[r]) or strs[r][c] != letter:
                    return strs[0][0:c]
        return strs[0]
